begin;
create table public.flag_requests(id uuid primary key default gen_random_uuid(), rider_id uuid not null references public.riders(id), spot_id uuid not null references public.spots(id), status text not null default 'pending' check(status in ('pending','approved','rejected')), unique(rider_id,spot_id));
alter table public.flag_requests enable row level security;
revoke all on public.flag_requests from public,anon,authenticated;
grant select on public.flag_requests to authenticated;
create policy flag_read on public.flag_requests for select to authenticated using(public.is_active_rider() and (rider_id=auth.uid() or public.is_admin()));
create function public.request_flag(target uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not public.is_active_rider() or not exists(select 1 from public.spots where id=target and status='approved') then raise exception 'Non autorizzato'; end if; insert into public.flag_requests(rider_id,spot_id) values(auth.uid(),target) on conflict do nothing; end; $$;
create function public.beta_moderate(kind text,target uuid,decision text,why text) returns void language plpgsql security definer set search_path='' as $$ declare n integer; begin if not public.is_admin() or decision not in ('approved','rejected') or coalesce(length(trim(why)),0)=0 or kind not in ('spots','media','comments','flag_requests') then raise exception 'Non autorizzato'; end if; execute format('update public.%I set status=$1 where id=$2 and status=''pending''',kind) using decision,target; get diagnostics n=row_count; if n<>1 then raise exception 'Contenuto non in attesa'; end if; if kind='flag_requests' and decision='approved' then insert into public.conquests(rider_id,spot_id) select rider_id,spot_id from public.flag_requests where id=target on conflict do nothing; end if; insert into public.moderation_log(moderator_id,content_type,content_id,decision,reason) values(auth.uid(),kind,target,decision,why); end; $$;
create function public.beta_ranking(scope text,territory text,monthly boolean) returns table(nickname text,flags bigint) language sql stable security definer set search_path='' as $$ select r.nickname,count(*) from public.conquests c join public.riders r on r.id=c.rider_id join public.spots s on s.id=c.spot_id where public.is_active_rider() and r.active and s.status='approved' and (not monthly or c.conquered_at>=date_trunc('month',now())) and (scope='national' or scope='province' and lower(s.province)=lower(territory) or scope='city' and lower(s.city)=lower(territory) or scope='region' and lower(s.region)=lower(territory)) group by r.id,r.nickname order by count(*) desc,r.nickname; $$;
revoke all on function public.request_flag(uuid),public.beta_moderate(text,uuid,text,text),public.beta_ranking(text,text,boolean) from public,anon;
grant execute on function public.request_flag(uuid),public.beta_moderate(text,uuid,text,text),public.beta_ranking(text,text,boolean) to authenticated;
revoke update on public.spots,public.media,public.comments from authenticated;
revoke update(status) on public.spots,public.media,public.comments from authenticated;
commit;
